const j=$input.first().json;const h=j.headers||{};
if(h['x-secret']!=='b3834c50c9d39e4e6a22ceb6a4b13950')throw new Error('forbidden');
const b=j.body||{};
const items=b.items||[],descs=b.descs||[],shots=b.shots||[];
const ids=[...new Set([...items.map(i=>i.key_id),...descs.map(d=>d.key_id),...shots.map(s=>s.key_id)])];
return [{json:{items,descs,shots,mode:b.mode||'test',dry:!!b.dry,ids:ids.join(',')}}];

const P='https://api.lokalise.com/api2/projects/479073796a6095e8c10e35.09051894';
const c=$('Check').first().json;const b=$('Fetch Current').first().json.body||{};const sb=$input.first().json.body||{};
if(!Array.isArray(b.keys))throw new Error('fetch failed '+JSON.stringify(b).slice(0,200));
if(!Array.isArray(sb.screenshots))throw new Error('shots fetch failed');
const LING=new Set('qrcodelocalization@gmail.com sabrathan@gmail.com farahputri@gmail.com dmluciahorea@gmail.com roxanamoldovan25@gmail.com mteres@terestraducciones.com arandatrad@gmail.com sara.guinot.trad@gmail.com daniel@dgmultilingualservices.com root-translations@outlook.com austra.muizniece@gmail.com harald.roald@gmail.com 47natcha@gmail.com ellen.de.venter@outlook.com ilaria.roncaglia@gmail.com silke.luehrmann@gmx.de boh.vozniuk@gmail.com vidiasc@gmail.com ivanaturcin@ymail.com julius.valkiunas@gmail.com jaromirvicari@me.com karahansisman@gmail.com katri.varvikko@gmail.com kenneth@phraseit.dk translation@cornell.hu ruckova.lucia@gmail.com marit.teichmann@gmail.com michal.tosza@translators.org.pl mteixeira@sacradomus.com bruno@bsttranslations.com nerissaneptuno@gmail.com straus.translations@gmail.com quentinnguyen.localize@gmail.com therese.svardsten@gmail.com mjlocalize@gmail.com silis.martins@gmail.com'.split(' '));
const keys={};const map={};for(const k of b.keys){keys[k.key_id]=k;for(const t of (k.translations||[]))map[k.key_id+'|'+t.language_iso]=t;}
const out=[];const skipped=[];
for(const it of c.items){const k=keys[it.key_id];if(!k||k.is_archived){skipped.push({k:it.key_id,why:'missing/archived'});continue;}
 const t=map[it.key_id+'|'+it.iso];if(!t){skipped.push({k:it.key_id,iso:it.iso,why:'no slot'});continue;}
 const cur=typeof t.translation==='string'?t.translation:JSON.stringify(t.translation);
 if(cur===it.text&&!t.is_unverified){skipped.push({k:it.key_id,iso:it.iso,why:'already done'});continue;}
 if(cur!==it.old&&cur!==it.text){skipped.push({k:it.key_id,iso:it.iso,why:'changed since fetch by '+t.modified_by_email});continue;}
 if(LING.has(t.modified_by_email)){skipped.push({k:it.key_id,iso:it.iso,why:'linguist edit '+t.modified_by_email});continue;}
 out.push({json:{kind:'tr',method:'PUT',url:P+'/translations/'+t.translation_id,key_id:it.key_id,iso:it.iso,want:it.text,body:{translation:it.text,is_unverified:false}}});}
if(c.mode==='test'){const first=out.slice(0,1);$getWorkflowStaticData('global').last={skipped};return c.dry?[{json:{none:true,dry:true,would:first}}]:first;}
for(const d of c.descs){const k=keys[d.key_id];if(!k||k.is_archived){skipped.push({k:d.key_id,why:'desc: missing/archived'});continue;}
 if(String(k.description||'').trim()){skipped.push({k:d.key_id,why:'desc exists'});continue;}
 out.push({json:{kind:'desc',method:'PUT',url:P+'/keys/'+d.key_id,key_id:d.key_id,want:d.text,body:{description:d.text}}});}
const byShot={};for(const s of c.shots){(byShot[s.shot_id]=byShot[s.shot_id]||[]).push(s.key_id);}
const cs={};for(const s of sb.screenshots)cs[s.screenshot_id]=s.key_ids||[];
for(const sid of Object.keys(byShot)){if(!cs[sid]){skipped.push({shot:sid,why:'screenshot not found'});continue;}
 const merged=[...new Set([...cs[sid],...byShot[sid]])];if(merged.length===cs[sid].length){skipped.push({shot:sid,why:'already linked'});continue;}
 out.push({json:{kind:'shot',method:'PUT',url:P+'/screenshots/'+sid,shot:Number(sid),want:merged,body:{key_ids:merged}}});}
$getWorkflowStaticData('global').last={skipped};
if(c.dry)return [{json:{none:true,dry:true,would_write:out.length,kinds:out.map(o=>o.json.kind),skipped}}];
if(!out.length)return [{json:{none:true,written_ok:0,skipped}}];
return out;

const res=$input.all();const req=$('Build').all();const st=$getWorkflowStaticData('global').last||{};
if(req.length&&req[0].json.none)return [req[0].json];
let ok=0;const bad=[];const done={tr:0,desc:0,shot:0};
for(let i=0;i<res.length;i++){const r=res[i].json;const q=req[i].json;const body=r.body||{};let good=false;
 if(q.kind==='tr'){const tr=body.translation||{};good=r.statusCode===200&&tr.translation===q.want&&tr.is_unverified===false;}
 else if(q.kind==='desc'){const k=body.key||{};good=r.statusCode===200&&k.description===q.want;}
 else if(q.kind==='shot'){const s=body.screenshot||{};const got=new Set(s.key_ids||[]);good=r.statusCode===200&&q.want.every(x=>got.has(x));}
 if(good){ok++;done[q.kind]++;}else bad.push({kind:q.kind,k:q.key_id||q.shot,iso:q.iso,status:r.statusCode,err:JSON.stringify(body.error||body).slice(0,200)});}
return [{json:{written_ok:ok,done,bad,skipped:st.skipped||[]}}];
